mapper.select:
select count(*) record_count,count(distinct customer_no) customer_count,ifnull(sum(ead_amount),0) total_ead,
       ifnull(sum(el_avg),0) total_el_avg,ifnull(sum(el_downturn),0) total_el_downturn
from risk_month_end_exposure_snapshot where batch_id=#{batchId}

select * from risk_month_end_change_detail
where current_batch_id=#{currentBatchId} and base_batch_id=#{baseBatchId}
order by abs(ead_delta)+abs(el_delta) desc,id desc limit #{limit}

select count(*) total_count,sum(status='OPEN') open_count,sum(status='PROCESSING') processing_count,
       sum(status='RESOLVED') resolved_count,sum(issue_level='HIGH' and status!='RESOLVED') high_open_count
from risk_month_end_quality_issue where batch_id=#{batchId}

select

    industry_name node_key,industry_name node_name,'INDUSTRY' node_level,
    customer_no node_key,max(customer_name) node_name,'CUSTOMER' node_level,
    contract_no node_key,contract_no node_name,'CONTRACT' node_level,
    debt_no node_key,debt_no node_name,'DEBT' node_level,

count(*) item_count,count(distinct customer_no) customer_count,sum(previous_ead) previous_ead,sum(current_ead) current_ead,
sum(ead_delta) ead_delta,sum(el_delta) el_delta,sum(current_default_flag) default_count,max(change_type) main_change_type
from risk_month_end_change_detail
where current_batch_id=#{currentBatchId} and base_batch_id=#{baseBatchId}
and industry_name=#{industry}
and customer_no=#{customerNo}
and contract_no=#{contractNo}
and change_type=#{changeType}

    group by industry_name
    group by customer_no
    group by contract_no
    group by debt_no

order by abs(sum(ead_delta))+abs(sum(el_delta)) desc limit #{limit}
